public sealed class CheckoutCoordinator
{
    private readonly IPriceCalculator _prices;
    private readonly IPromotionService _promotions;
    private readonly ITenderResolver _tenders;

    public CheckoutCoordinator(
        IPriceCalculator prices,
        IPromotionService promotions,
        ITenderResolver tenders)
    {
        _prices = prices;
        _promotions = promotions;
        _tenders = tenders;
    }

    public CheckoutResult Complete(
        CheckoutSession session, Order order, Customer customer)
    {
        if (!session.HasStarted)
            return CheckoutResult.NotStarted();

        var total = _prices.Calculate(order, customer);
        var tender = _tenders.Resolve(order, customer, total);
        return CheckoutResult.Completed(total, tender);
    }
}

Promotion redemption and audit storage should be implemented by dedicated, appropriately scoped services so separate checkouts cannot share accidental in-memory state.
